<?php

namespace App\Libraries;

/** Derivatives are generated by CLI, never during a public request. */
class ResponsiveCover
{
    public const WIDTHS = [480, 800, 1200, 1600];

    public function describe(string $path): array
    {
        $root = realpath(FCPATH . 'uploads/heroes');
        $source = realpath(FCPATH . ltrim($path, '/\\'));
        if (! $root || ! $source || ! str_starts_with(strtolower($source), strtolower($root . DIRECTORY_SEPARATOR))) {
            return [];
        }
        $size = @getimagesize($source);
        if (! $size || ! in_array($size[2], [IMAGETYPE_JPEG, IMAGETYPE_PNG, IMAGETYPE_WEBP], true)) {
            return [];
        }
        $key = substr(hash('sha256', $path . ':' . filemtime($source) . ':' . filesize($source) . ':v1'), 0, 24);
        $variants = [];
        foreach (self::WIDTHS as $width) {
            if ($width > $size[0]) continue;
            $relative = 'uploads/heroes/responsive/' . $key . '-' . $width . '.webp';
            if (is_file(FCPATH . $relative)) $variants[$width] = $relative;
        }
        return ['source' => $source, 'width' => $size[0], 'height' => $size[1], 'key' => $key, 'variants' => $variants];
    }

    public function generate(string $path): array
    {
        $info = $this->describe($path);
        if (! $info) throw new \RuntimeException('Unsupported cover path or image.');
        if (! function_exists('imagewebp')) throw new \RuntimeException('GD WebP support is required.');
        if ($info['width'] * $info['height'] > 30000000) throw new \RuntimeException('Cover exceeds the 30 megapixel processing limit.');
        $directory = FCPATH . 'uploads/heroes/responsive';
        if (! is_dir($directory) && ! mkdir($directory, 0755, true) && ! is_dir($directory)) {
            throw new \RuntimeException('Cannot create derivative directory.');
        }
        $image = null;
        try {
            foreach (self::WIDTHS as $width) {
                if ($width > $info['width'] || isset($info['variants'][$width])) continue;
                if ($image === null) {
                    // Avoid changing EXIF-oriented photographs during re-encoding.
                    if (function_exists('exif_read_data') && exif_imagetype($info['source']) === IMAGETYPE_JPEG) {
                        $exif = @exif_read_data($info['source']);
                        if ((int) ($exif['Orientation'] ?? 1) > 1) {
                            throw new \RuntimeException('EXIF orientation requires normalization; original retained.');
                        }
                    }
                    $image = match (exif_imagetype($info['source'])) {
                        IMAGETYPE_JPEG => imagecreatefromjpeg($info['source']),
                        IMAGETYPE_PNG => imagecreatefrompng($info['source']),
                        IMAGETYPE_WEBP => imagecreatefromwebp($info['source']),
                    };
                    if (! $image) throw new \RuntimeException('Cannot decode cover.');
                }
                $height = max(1, (int) round($info['height'] * $width / $info['width']));
                $target = imagecreatetruecolor($width, $height);
                imagealphablending($target, false);
                imagesavealpha($target, true);
                imagecopyresampled($target, $image, 0, 0, 0, 0, $width, $height, $info['width'], $info['height']);
                $destination = $directory . '/' . $info['key'] . '-' . $width . '.webp';
                $temporary = tempnam($directory, '.cover-');
                try {
                    if (! $temporary || ! imagewebp($target, $temporary, 84)) throw new \RuntimeException('Cannot encode WebP.');
                    chmod($temporary, 0644);
                    if (! rename($temporary, $destination)) throw new \RuntimeException('Cannot publish derivative.');
                } finally {
                    imagedestroy($target);
                    if ($temporary && is_file($temporary)) unlink($temporary);
                }
            }
        } finally {
            if ($image) imagedestroy($image);
        }
        return $this->describe($path);
    }
}
